import re

class BoyerMooreSearch:
    def __init__(self, text, pattern):
        self._text = text
        self._pattern = pattern
        self._textLen = len(text)
        self._patLen = len(pattern)

    @property
    def text(self):
        return self._text

    @property
    def pattern(self):
        return self._pattern

    @property
    def textLen(self):
        return self._textLen

    @property
    def patLen(self):
        return self._patLen

    def match_in_pattern(self, char):
        for i in range(self.patLen - 1, -1, -1):
            if char == self.pattern[i]:
                return i
        return -1

    def mismatch_in_text(self, currentPos):
        for i in range(self.patLen - 1, -1, -1):
            if self.pattern[i] != self.text[currentPos + i]:
                return currentPos + i
        return -1

    def find_bad_character_shift(self, mismatch_index, char):
        match_index = self.match_in_pattern(char)
        return mismatch_index - match_index

    def bad_character_heuristic(self):
        positions = []
        i = 0
        while i <= self.textLen - self.patLen:
            mismatch_index = self.mismatch_in_text(i)
            if mismatch_index == -1:
                positions.append(i)
                i += 1
            else:
                char = self.text[mismatch_index]
                positions.append(i + self.find_bad_character_shift(mismatch_index, char))
                i += self.find_bad_character_shift(mismatch_index, char)
        return positions
